(function () {
    let html = '';
    let inCode = false;
    let codeContent = '';
    let inTable = false;
    let tableHeaders: string[] = [];
    let tableRows: string[] = [];

    const flushTable = () => {
      if (tableHeaders.length && tableRows.length) {
        html +=
          '<table><tr>' +
          tableHeaders.map((h) => '<td><strong>' + h + '</strong></td>').join('') +
          '</tr>' +
          tableRows.join('') +
          '</table>';
      }
      tableHeaders = [];
      tableRows = [];
      inTable = false;
    };

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];
      if (line.startsWith('```')) {
        if (inCode) {
          html += '<div class="code-block">' + codeContent + '</div>';
          codeContent = '';
          inCode = false;
        } else {
          inCode = true;
        }
        continue;
      }
      if (inCode) {
        codeContent += line + '\n';
        continue;
      }
      if (line.startsWith('# ')) continue;
      if (line.startsWith('*Generated')) continue;
      if (line.startsWith('---')) {
        flushTable();
        html += '<hr/>';
        continue;
      }
      if (line.trim() === '') {
        flushTable();
        continue;
      }

      if (line.startsWith('| ') && line.endsWith('|')) {
        const cells = line
          .split('|')
          .filter(Boolean)
          .map((c) => c.trim().replace(/\*\*/g, '').replace(/`/g, ''));
        if (i + 1 < lines.length && lines[i + 1].includes('---')) {
          tableHeaders = cells;
          inTable = true;
          i++;
          continue;
        }
        if (inTable) {
          tableRows.push('<tr>' + cells.map((c) => '<td>' + c + '</td>').join('') + '</tr>');
        }
        continue;
      }

      flushTable();

      if (line.startsWith('## ')) {
        html += '<h2>' + line.replace('## ', '') + '</h2>';
        continue;
      }
      if (line.startsWith('### ')) {
        html += '<h3>' + line.replace('### ', '') + '</h3>';
        continue;
      }
      if (line.startsWith('- ')) {
        html += '<li>' + line.replace('- ', '') + '</li>';
        continue;
      }
      const processed = line
        .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
        .replace(/`(.*?)`/g, '<code>$1</code>');
      if (
        processed.startsWith('⚠️') ||
        processed.startsWith('🌐') ||
        processed.startsWith('❌') ||
        processed.startsWith('✅')
      ) {
        html += '<div class="warning">' + processed + '</div>';
      } else {
        html += '<p>' + processed + '</p>';
      }
    }

    flushTable();
    return html;
  })

